export const ALL_WORDS = Object.entries(LISTS).flatMap(([category, words]) => words.map((word) => ({ word, category })));
export function wordsFor(category, variant) {
    let pool = category === 'misto' ? ALL_WORDS : ALL_WORDS.filter((w) => w.category === category);
    // ações são ótimas para mímica, mas difíceis de desenhar só com "misto"
    if (category === 'misto' && variant === 'draw')
        pool = pool.filter((w) => w.category !== 'acoes');
    return pool;
}
